  ]);
});
```

**Install dependency:**
```bash
npm install express-rate-limit
```

---

### 5. **Missing JSON Body Parser Configuration** (OWASP A03:2021 - Injection)

**Issue:** `express.json()` not enabled, causing potential errors with POST/PUT requests.

**FIXED CODE:**
```javascript
// Add before routes
app.use(express.json({
  limit: '10kb', // Limit payload size to prevent DoS
  verify: (req, res, buf) => {
    req.body = buf.toString('utf8');
  }
}));

app.use(express.urlencoded({
  extended: true,
  limit: '10kb',
}));
```

---

### 6. **Missing Server-Side Request Forgery (SSRF) Protection** (Potential Issue)

**Issue:** No protection if endpoints were to fetch external resources in future.

**FIXED Code (防御性编程):**
```javascript
const { network conditions, sanitizeUrl } = require('url');

function validateSSRF(url) {
  // Block internal network ranges and localhost
  const forbiddenIPs = ['127.0.0.1', '::1', '0.0.0.0', 'localhost'];

  try {
    const parsedUrl = new URL(url);
    const hostname = parsedUrl.hostname;

    // Check if host is in forbidden list
    if (forbiddenIPs.includes(hostname)) {
      throw new Error('Internal network requests are forbidden');
    }

    // Basic sanitization
    return sanitizeUrl(url);
  } catch (error) {
    throw new Error('Invalid URL provided');
  }
}
```

