### 7. **No Authentication / Authorization** (OWASP A07:2021)

**Issue:** No authentication mechanism for any endpoint.

**FIXED CODE:**
```javascript
const bcrypt = require('bcrypt');
const jwt = require('jsonwebtoken');

const JWT_SECRET = process.env.JWT_SECRET || 'CHANGE_THIS_TO_A_SECURE_RANDOM_SECRET';
const ACCESS_TOKEN_EXPIRY = '15m';
const REFRESH_TOKEN_EXPIRY = '7d';

// Simple password hashing function
async function hashPassword(password) {
  const saltRounds = 12;
  return await bcrypt.hash(password, saltRounds);
}

async function checkPassword(password, hashedPassword) {
  return await bcrypt.compare(password, hashedPassword);
}

// Authentication middleware
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, JWT_SECRET, (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
}

// Example secured route
app.get('/users', authenticateToken, (req, res) => {
  // Only authenticated users can access
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

**Install dependencies:**
```bash
npm install bcrypt jsonwebtoken
```

---

### 8. **Debug Mode Enabled** (Security Misconfiguration)

**Issue:** No debug mode setting checked.

**FIXED Code:**
```javascript
// Ensure debug mode is disabled in production
if (app.get('env') === 'development') {
  app.use(morgan('dev')); // Logging
} else {
