/**
 * Secrets Management Utility
 * Provides centralized secret loading and validation
 */

const fs = require('fs');
const path = require('path');

class SecretManager {
  constructor() {
    this.secrets = {};
  }

  /**
   * Load environment variables from a .env file
   * @param {string} envFile - Path to .env file
   */
  loadFromFile(envFile) {
    const filePath = path.resolve(envFile);

    if (!fs.existsSync(filePath)) {
      console.warn(`Warning: .env file not found at ${filePath}`);
      return;
    }

    const content = fs.readFileSync(filePath, 'utf-8');
    const lines = content.split('\n');

    for (const line of lines) {
      // Skip comments and empty lines
      if (!line || line.trim().startsWith('#')) continue;

      // Match KEY=VALUE format
      const match = line.match(/^([^=]+)=(.*)$/);
      if (match) {
        const key = match[1].trim();
        const value = match[2].trim();

        // Remove quotes from value if present
        if ((value.startsWith('"') && value.endsWith('"')) ||
            (value.startsWith("'") && value.endsWith("'"))) {
          this.secrets[key] = value.slice(1, -1);
        } else {
          this.secrets[key] = value;
        }
      }
    }

    console.log(`Loaded ${Object.keys(this.secrets).length} secrets from ${envFile}`);
  }

  /**
   * Get a secret with a default value
   * @param {string} key - Secret key
   * @param {*} defaultValue - Default value if key not found
   * @returns {*} Secret value or default
   */
  get(key, defaultValue = null) {
    return this.secrets[key] || process.env[key] || defaultValue;
  }

  /**
   * Get a secret with validation
   * @param {string} key - Secret key
   * @param {Object} options - Validation options
   * @returns {*} Secret value
   * @throws {Error} If validation fails
   */
  getValidated(key, options = {}) {
    const value = this.get(key);

    // Check if required
    if (options.required && !value) {
      throw new Error(`Missing required secret: ${key}`);
    }

    if (!value) {
      return value;
    }

    // Validate minimum length
    if (options.minLength && value.length < options.minLength) {
      throw new Error(`Secret ${key} must be at least ${options.minLength} characters`);
    }

    // Validate pattern
    if (options.pattern && !options.pattern.test(value)) {
      throw new Error(`Secret ${key} does not match expected pattern`);
    }

    return value;
  }

  /**
   * Check if a secret is set
   * @param {string} key - Secret key
   * @returns {boolean}
   */
  has(key) {
    return !!(
      this.secrets[key] ||
      process.env[key]
    );
  }

  /**
   * Get all secrets
   * @returns {Object}
   */
  getAll() {
    return { ...process.env, ...this.secrets };
  }
}

// Singleton instance
const secretManager = new SecretManager();

module.exports = {
  secretManager,
  SecretManager
};

/**
 * Secure Application with Proper Secrets Management
 */

const express = require('express');
const helmet = require('helmet');
// const rateLimit = require('express-rate-limit');
// const cors = require('cors');

// Load environment variables first
const { SecretManager } = require('./secrets-manager');

const secretConfig = {
