    { required: true }
  ),

  jwtExpiry: process.env.JWT_EXPIRY || '15m',
  refreshTokenExpiry: process.env.REFRESH_TOKEN_EXPIRY || '7d',

  databaseUrl: secretManager.get('DATABASE_URL', null, { required: true }),
  databaseUrlV2: secretManager.get('DATABASE_URL_V2'),

  redisUrl: secretManager.get('REDIS_URL'),

  corsOrigins: secretManager.get(
    'CORS_ORIGINS',
    ['http://localhost:3000']
  ).split(',').map(s => s.trim()),

  stripeKey: process.env.STRIPE_PUBLIC_KEY,
  stripeSecret: secretManager.get('STRIPE_SECRET_KEY'),

  anthropicApiKey: secretManager.get('ANTHROPIC_API_KEY'),

  logfireToken: secretManager.get('LOGFIRE_TOKEN'),

  openaiApiKey: secretManager.get('OPENAI_API_KEY'),

  // Security settings
  rateLimiter: {
    windowMs: parseInt(process.env.RATE_LIMIT_WINDOW_MS) || 900000,
