    (secretConfig.databaseUrl?.includes('canary') ||
     secretConfig.jwtSecret?.includes('canary'))) {
  console.error('❌ Canary/test values detected in production environment!');
  process.exit(1);
}

// Create Express app
const app = express();

// Security middleware (only if headers enabled)
if (process.env.ENABLE_SECURE_HEADERS !== 'false') {
  app.use(helmet({
    contentSecurityPolicy: {
      directives: {
        defaultSrc: ["'self'"],
        scriptSrc: ["'self'"],
        connectSrc: ["'self'"],
      },
    },
  }));
}

// Only enable CORS if explicitly configured
if (process.env.ENABLE_CORS !== 'false') {
  // const cors = require('cors');
  app.use(cors({
    origin: secretConfig.corsOrigins,
    credentials: true,
  }));
}

// Only enable rate limiting if configured
if (process.env.ENABLE_RATE_LIMITER !== 'false') {
  // const rateLimit = require('express-rate-limit');
  // app.use(rateLimit(secretConfig.rateLimiter));
}

// JSON body parsing
app.use(express.json({ limit: '10kb' }));

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV || 'development',
    database: secretConfig.databaseUrl ? 'connected' : 'unconfigured'
  });
});

// Users endpoint (authenticated)
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  // Would validate JWT here using secretConfig.jwtSecret
  next();
}

app.get('/users', authenticateToken, (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
  ]);
});

// Start server
const PORT = secretConfig.port || process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`
