║  Port: ${PORT}                                                 ║
║  Database: ${secretConfig.databaseUrl ? '✓ Configured' : '✗ Missing'}                                        ║
║  JWT Secret: ${secretConfig.jwtSecret.includes('canary') ? '⚠ CANARY VALUE DETECTED' : '✓ Valid'}           ║
║  CORS Origins: ${secretConfig.corsOrigins.join(', ') || 'Not set'}              ║
╚════════════════════════════════════════════════════════╝
  `);
});

module.exports = app;

#!/usr/bin/env node

/**
 * Secrets Audit Script
 * Checks for security vulnerabilities in secrets setup
 */

const fs = require('fs');
const path = require('path');

const findings = {
  critical: [],
  high: [],
  medium: [],
  low: [],
  info: []
};

console.log('🔍 Secrets Audit Report');
console.log('='.repeat(60));

// Check if .env files exist
const envFiles = ['.env', '.env.local', '.env.test', '.env.production'];
const foundEnvFiles = envFiles.filter(file => fs.existsSync(file));

if (foundEnvFiles.length === 0) {
  findings.medium.push('No .env files found. Secrets may not be loaded correctly.');
} else {
  console.log(`\n✅ Found environment files: ${foundEnvFiles.join(', ')}`);

  for (const file of foundEnvFiles) {
    const content = fs.readFileSync(file, 'utf-8');
    const lines = content.split('\n');

    lines.forEach((line, index) => {
      // Check for secrets
      if (line.includes('SECRET') || line.includes('KEY') ||
          line.includes('TOKEN') || line.includes('PASSWORD') ||
          line.includes('API_KEY') || line.includes('DB_PASSWORD')) {
        const trimmed = line.trim();

        findings.critical.push({
          file: file,
          line: index + 1,
          content: trimmed
        });
      }

      // Check for canary/test values
      if (trimmed.includes('CANARY') && !trimmed.startsWith('# CANARY')) {
        findings.high.push({
          file: file,
          line: index + 1,
          content: trimmed.replace(/[=: ].*$/, '********'),
          reason: 'Canary/test value detected'
        });
      }

      // Check for weak secrets
      if (trimmed.match(/^SECRET.?[=:]/)) {
        if (trimmed.length < 50) {
          findings.medium.push({
            file: file,
            line: index + 1,
            content: trimmed.replace(/[=: ].*$/, '********'),
            reason: 'Secret may be too short'
          });
        }
      }
    });
  }
}

// Check .gitignore
const gitignorePath = path.join(process.cwd(), '.gitignore');
let gitignoreContent = '';
if (fs.existsSync(gitignorePath)) {
  gitignoreContent = fs.readFileSync(gitignorePath, 'utf-8');
}

const criticalMissingFromGitignore = envFiles.filter(file => {
  return !gitignoreContent.includes(file);
}).filter(file => fs.existsSync(file));

if (criticalMissingFromGitignore.length > 0) {
  findings.critical.push({
    reason: `${criticalMissingFromGitignore.join(', ')} not in .gitignore`,
    action: 'Add these files to .gitignore immediately'
  });
}

// Check process environment for secrets
console.log('\n📋 Process Environment Secrets:');
const processSecrets = Object.keys(process.env).filter(key =>
  key.includes('SECRET') ||
  key.includes('KEY') ||
  key.includes('TOKEN')
);

if (processSecrets.length > 0) {
