```javascript
// For AWS users: AWS Systems Manager Parameter Store
// For GCP users: Secret Manager
// For Azure users: Key Vault
// For on-prem: HashiCorp Vault

const { SSMClient, GetParameterCommand } = require('@aws-sdk/client-ssm');

async function getSecret(secretName) {
  const ssmClient = new SSMClient({ region: process.env.AWS_REGION });

  try {
    const response = await ssmClient.send(new GetParameterCommand({
      Name: `/prod/secrets/${secretName}`,
      WithDecryption: true,
      RetrievalOption: 'SecureString'
    }));

    return response.Parameter.Value;
  } catch (error) {
    throw new Error(`Failed to retrieve secret ${secretName}: ${error.message}`);
  }
}

async function loadProductionSecrets() {
  return {
    DATABASE_URL: await getSecret('database-url'),
    JWT_SECRET: await getSecret('jwt-sign-key'),
    JWT_REFRESH_SECRET: await getSecret('jwt-refresh-key'),
    SESSION_SECRET: await getSecret('session-key'),
    ENCRYPTION_KEY: await getSecret('encryption-key'),
    AWS_ACCESS_KEY_ID: process.env.AWS_ACCESS_KEY_ID,
    AWS_SECRET_ACCESS_KEY: process.env.AWS_SECRET_ACCESS_KEY
  };
}
