```javascript
// Role-based authorization
function authorizeRole(...roles) {
  return (req, res, next) => {
    if (!req.user) {
      return res.sendStatus(401);
    }

    if (!roles.includes(req.user.role)) {
      return res.status(403).json({ message: 'Forbidden' });
    }

    next();
  };
}

// Or permission-based
const permissions = {
  admin: ['create', 'read', 'update', 'delete'],
  user: ['read'],
  guest: ['read']
};

function authorizePermission(action) {
  return (req, res, next) => {
    if (!req.user || !permissions[req.user.role]?.includes(action)) {
      return res.status(403).json({ message: 'Forbidden' });
    }
    next();
  };
}

// Usage
// Admin only
app.delete('/users/:id', 
  authenticateToken, 
  authorizeRole('admin'),
  async (req, res) => {
    await deleteUser(req.params.id);
    res.json({ message: 'User deleted' });
  }
);

// Any authenticated user can create their own
app.post('/users',
  authenticateToken,
  authorizePermission('create'),
  (req, res) => {
    // ... 
  }
);
```

