### 7. ⚠️ Missing Error Handling & Sanitization

**Issue:** Generic error handling visible to users; no error sanitization.

**Risk:** Information disclosure via error stack traces; potential DoS vulnerability.

**Recommendation:** Implement proper error handling
```javascript
// Use built-in express error handler with sanitization
const logger = require('morgan');

// Only show logs in development
app.use(logger(process.env.NODE_ENV === 'development' ? 'dev' : 'combined'));

// global error handler
app.use((err, req, res, next) => {
  // In production, sanitize error details
  const statusCode = err.statusCode || 500;
  const message = process.env.NODE_ENV === 'production'
    ? 'Internal server error'
    : err.message;

  res.status(statusCode).json({
    error: {
      message,
      ...(process.env.NODE_ENV !== 'production' && { stack: err.stack })
    }
  });
});

// Handle 404
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});

// Startup health endpoint
app.get('/health', (req, res) => {
  try {
    // Check dependencies (DB, etc.)
    res.json({
      status: 'healthy',
      uptime: process.uptime(),
      timestamp: new Date().toISOString()
    });
  } catch (error) {
    res.status(503).json({
      status: 'unhealthy',
      error: error.message
    });
  }
});
```

