## 🔒 Production Secrets Management (AWS Parameter Store)

```javascript
// lib/secrets-manager.js
const { SSMClient, GetParameterCommand } = require('@aws-sdk/client-ssm');
const crypto = require('crypto');

let client;
let cachedSecrets = {};

async function getSSMClient() {
  if (!client) {
    client = new SSMClient({ region: process.env.AWS_REGION || 'us-east-1' });
  }
  return client;
}

async function getSecrets() {
  const client = await getSSMClient();
  const secrets = process.env;

  // Fetch critical secrets from SSM if not in environment
  const paramNames = [
    '/app/database-url',
    '/app/stripe-secret-key',
    '/app/anthropic-api-key'
  ];

  for (const name of paramNames) {
    if (!secrets[name.replace('/app/', '').replace(/-/g, '_')]) {
      try {
        const command = new GetParameterCommand({
          Name: name,
          WithDecryption: true
        });
        const response = await client.send(command);
        cachedSecrets[name] = response.Parameter.Value;
        secrets[name.replace('/app/', '').replace(/-/g, '_')] = response.Parameter.Value;
      } catch (error) {
        console.warn(`Failed to fetch secret ${name}:`, error.message);
      }
    }
  }

  return secrets;
}

function encryptSecret(secret) {
  const iv = crypto.randomBytes(16);
  const cipher = crypto.createCipheriv('aes-256-cbc', Buffer.from(process.env.ENCRYPTION_KEY || 'default-key'), iv);
  return {
    encrypted: cipher.update(secret, 'utf8', 'hex') + cipher.final('hex'),
    iv: iv.toString('hex')
  };
}

module.exports = {
  getSSMClient,
  getSecrets,
  encryptSecret
};
```

