// Secure application with OWASP Best Practices
const express = require('express');
const jwt = require('jsonwebtoken');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const validator = require('validator');

const app = express();

// 1. Security Headers
app.use(helmet({
  hsts: {
    maxAge: 31536000, // 1 year
    includeSubDomains: true,
    preload: true
  },
  xssFilter: true,
  noSniff: true,
  hidePoweredBy: true
}));

// 2. Rate Limiting
const limiter = rateLimit({
  windowMs: 60 * 1000, // 1 minute
  max: 60, // 60 requests per minute
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later in 1 minute.' }
});
app.use(limiter);

// 3. Input Validation Utilities
const validators = {
  email: (str) => validator.isEmail(str),
  username: (str) => validator.escape(str).length >= 3 && validator.escape(str).length <= 20,
  text: (str) => validator.isAlphanumeric(str.replace(/[\s.,!?]/g, '')) && str.trim().length > 0,
  integer: (num) => Number.isInteger(parseInt(num))
};

function validateNestedPath(str) {
  const parts = str.split('/');
  return parts.every(part => validator.escape(part) === part);
}

function validateRequestBody(req, schema) {
  for (const [field, rule] of Object.entries(schema)) {
    if (req.body[field] === undefined) {
      return { valid: false, field, message: `${field} is required` };
    }
    if (rule.type === 'email' && !validators.email(req.body[field])) {
      return { valid: false, field, message: 'Invalid email format' };
    }
    if (rule.type === 'username' && !validators.username(req.body[field])) {
      return { valid: false, field, message: 'Username must be 3-20 alphanumeric characters' };
    }
    if (rule.regex && !rule.regex.test(req.body[field])) {
      return { valid: false, field, message: rule.message || `${field} is invalid` };
    }
  }
  return { valid: true };
}

// 4. Authentication Middleware
const config = {
  jwtSecret: process.env.JWT_SECRET || (() => {
    if (process.env.NODE_ENV === 'production') {
      throw new Error('JWT_SECRET must be set in production');
    }
    return 'dev-secret-key';
  })(),
  port: (() => {
    const port = process.env.PORT || 3000;
    if (isNaN(port) || port < 1 || port > 65535) {
      throw new Error(`Invalid PORT: ${port}`);
    }
    return port;
  })()
};

function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader?.startsWith('Bearer ') ? authHeader.split(' ')[1] : null;

  if (!token) {
    return res.status(401).json({ error: 'Access denied. No token provided.' });
  }

  jwt.verify(token, config.jwtSecret, (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid or expired token.' });
    }
    req.user = user;
    next();
  });
}

// 5. Error Handling middleware
app.use((err, req, res, next) => {
  console.error('Error:', err);
  res.status(err.status || 500).json({
    error: err.message || 'Internal server error',
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined
  });
});

// Secure Health Endpoint
app.get('/health', (req, res) => {
  res.status(200).json({
    status: 'ok',
    timestamp: new Date().toISOString() // Only show generic timestamp
  });
});

// Protected User Endpoint
app.get('/users', authenticateToken, (req, res) => {
  // Validate query parameters if present
  if (req.query.id && !validators.integer(req.query.id)) {
    return res.status(400).json({ error: 'Invalid user ID' });
  }

  // Return mock data (in production, this would query a database)
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' }
  ]);
});

// Secure POST endpoint example
app.post('/api/alerts', authenticateToken, (req, res) => {
  // Validate request body
  const validation = validateRequestBody(req, {
    message: { type: 'text', regex: /^[\w\s.,!?]*$/, message: 'Invalid message format' }
  });

  if (!validation.valid) {
    return res.status(400).json({ error: validation.message });
  }

  // Process the data securely
  const alertMessage = validator.escape(req.body.message);
  res.status(201).json({ success: true, message: 'Alert created' });
});

// Start server
app.listen(config.port, () => {
  console.log(`Server running on port ${config.port}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

module.exports = app;

