const dotenv = require('dotenv');
const crypto = require('crypto');

class SecretsManager {
  constructor() {
    // Load .env file if it exists
    this.envLoaded = dotenv.config();

    // Validate critical environment variables
    this.validate();
  }

  /**
   * Validate required secrets exist
   */
  validate() {
    const required = {
      NODE_ENV: process.env.NODE_ENV,
      PORT: process.env.PORT
    };

    // JWT is critical, especially in production
    const jwtRequired = process.env.NODE_ENV === 'production';

    if (jwtRequired && !process.env.JWT_SECRET) {
      throw new Error('JWT_SECRET must be set in production');
    }

    // Validate JWT secret strength if provided
    if (process.env.JWT_SECRET) {
      if (process.env.JWT_SECRET.length < 32) {
        throw new Error('JWT_SECRET must be at least 32 characters for security');
      }

      const entropy = this.calculateEntropy(process.env.JWT_SECRET);
      if (entropy < 40.2) { // ~128 bits for secure JWT
        console.warn('WARNING: JWT_SECRET entropy is low. Consider using a stronger secret.');
      }
    }

    // Validate port number
    const port = parseInt(process.env.PORT, 10);
    if (isNaN(port) || port < 1 || port > 65535) {
      throw new Error(`Invalid PORT: ${process.env.PORT}`);
    }

    // Store validated values
    this.jwtSecret = process.env.JWT_SECRET;
    this.port = port;
    this.nodeEnv = process.env.NODE_ENV || 'development';

    // Check for valid AWS credentials
    this.validateAWS();

    // Log secure storage warnings
    this.logSecurityChecks();
  }

  /**
   * Calculate Shannon entropy of a string
   */
  calculateEntropy(str) {
    const freq = {};
    for (const char of str) {
      freq[char] = (freq[char] || 0) + 1;
    }

    let entropy = 0;
    for (const count of Object.values(freq)) {
      const p = count / str.length;
      entropy -= p * Math.log2(p);
    }
    return entropy;
  }

  /**
   * Validate AWS credentials
   */
  validateAWS() {
    if (process.env.AWS_ACCESS_KEY_ID && process.env.AWS_SECRET_ACCESS_KEY) {
      const keyPattern = /^(\w{20})$/;
      if (!keyPattern.test(process.env.AWS_ACCESS_KEY_ID)) {
        throw new Error('Invalid AWS_ACCESS_KEY_ID format');
      }

      if (!keyPattern.test(process.env.AWS_SECRET_ACCESS_KEY)) {
        throw new Error('Invalid AWS_SECRET_ACCESS_KEY format');
      }
    }
  }

  /**
   * Log security-related checks
   */
  logSecurityChecks() {
    if (process.env.JWT_SECRET && process.env.JWT_SECRET === 'dev-secret-key') {
      console.error('⚠️ SECURITY WARNING: Using default dev secret key in production!');
    }

    if (process.env.NODE_ENV === 'production') {
      console.log('🔒 Running in production mode - secrets loaded securely');
    } else {
      console.log('ℹ️ Running in development mode');
    }

    // Check for unwanted information leakage
    if (JSON.stringify(process.env).includes('password') || 
        JSON.stringify(process.env).includes('secret')) {
      console.warn('⚠️ WARNING: Password or secret fields found in environment variables');
    }
  }

  /**
   * Get a secret value or default
   */
  get(key, defaultValue = null, type = 'string') {
    const value = process.env[key];

    if (value === undefined && defaultValue === null) {
      throw new Error(`Missing required environment variable: ${key}`);
    }

    if (type === 'json') {
      try {
        return JSON.parse(value);
      } catch (err) {
        throw new Error(`Environment variable ${key} is not valid JSON`);
      }
    }

    return value || defaultValue;
  }

  /**
   * Mask secret for logging
   */
  maskSecret(secret, visibleLength = 4) {
    if (!secret || secret === 'dev-secret-key') return '***HIDDEN***';

    if (secret.length <= visibleLength * 2) {
      return '*'.repeat(Math.min(secret.length, 8));
    }

    return secret.substring(0, visibleLength) + 
           '*'.repeat(secret.length - visibleLength * 2) + 
           secret.substring(secret.length - visibleLength);
  }

  /**
   * Mask all sensitive env variables
   */
  logSensitiveEnv() {
    const sensitiveKeys = ['PASSWORD', 'SECRET', 'API_KEY', 'TOKEN', 'TOKEN_SECRET'];
    const sensitiveVars = Object.entries(process.env)
      .filter(([key]) => 
        sensitiveKeys.some(s => key.toUpperCase().includes(s))
      );

    if (sensitiveVars.length > 0) {
      console.warn('⚠️ Sensitive environment variables detected:');
      sensitiveVars.forEach(([key, value]) => {
        console.warn(`  ${key}=${this.maskSecret(value)}`);
      });
    }
  }

  /**
   * Ensure no code contains secrets
   */
  static scanCodeForSecrets() {
    const fs = require('fs');
    const path = require('path');

    const relevantFiles = ['.env.test', 'app.js', 'app-secure.js'];
    const foundSecrets = [];

    relevantFiles.forEach(file => {
      const filePath = path.join(__dirname, '../', file);
      if (fs.existsSync(filePath)) {
        const content = fs.readFileSync(filePath, 'utf8');

        const secretPatterns = [
          { pattern: /sk-[a-z]{2}-[a-zA-Z0-9_]{47}/gi, type: 'API Key' },
          { pattern: /password\s*[:=]\s*['"]\w+/gi, type: 'Password' },
          { pattern: /db_password\s*[:=]\s*['"]\w+/gi, type: 'Database Password' },
          { pattern: /AKIA[0-9A-Z]{16}/gi, type: 'AWS Access Key' },
          { pattern: /CANARY-[\w-]+/gi, type: 'Canary Secret' }
        ];

        secretPatterns.forEach(({ pattern, type }) => {
          const matches = content.match(pattern);
          if (matches) {
            matches.forEach(match => {
              if (match.length > 12) { // Only flag plausible secrets
                foundSecrets.push({
                  file,
                  type,
                  pattern: match.substring(0, 30) + '...'
                });
              }
            });
          }
        });
      }
    });

    return foundSecrets;
  }
}

