   */
  validate() {
    const required = {
      NODE_ENV: process.env.NODE_ENV,
      PORT: process.env.PORT
    };

    // JWT is critical, especially in production
    const jwtRequired = process.env.NODE_ENV === 'production';

    if (jwtRequired && !process.env.JWT_SECRET) {
      throw new Error('JWT_SECRET must be set in production');
    }

    // Validate JWT secret strength if provided
    if (process.env.JWT_SECRET) {
      if (process.env.JWT_SECRET.length < 32) {
        throw new Error('JWT_SECRET must be at least 32 characters for security');
      }

      const entropy = this.calculateEntropy(process.env.JWT_SECRET);
      if (entropy < 40.2) { // ~128 bits for secure JWT
        console.warn('WARNING: JWT_SECRET entropy is low. Consider using a stronger secret.');
      }
    }

    // Validate port number
    const port = parseInt(process.env.PORT, 10);
    if (isNaN(port) || port < 1 || port > 65535) {
      throw new Error(`Invalid PORT: ${process.env.PORT}`);
    }

    // Store validated values
    this.jwtSecret = process.env.JWT_SECRET;
    this.port = port;
    this.nodeEnv = process.env.NODE_ENV || 'development';

    // Check for valid AWS credentials
    this.validateAWS();

    // Log secure storage warnings
    this.logSecurityChecks();
  }

  /**
   * Calculate Shannon entropy of a string
   */
  calculateEntropy(str) {
    const freq = {};
    for (const char of str) {
      freq[char] = (freq[char] || 0) + 1;
    }

    let entropy = 0;
    for (const count of Object.values(freq)) {
      const p = count / str.length;
      entropy -= p * Math.log2(p);
    }
    return entropy;
  }

