// Secure application with OWASP Best Practices
const express = require('express');
const jwt = require('jsonwebtoken');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const validator = require('validator');

// Import secrets manager
const { SecretsManager } = require('./config/secrets.js');

// Initialize secrets (this loads .env and validates credentials)
const secrets = new SecretsManager();

const app = express();

// 1. Security Headers
app.use(helmet({
  hsts: {
    maxAge: 31536000, // 1 year
    includeSubDomains: true,
    preload: true
  },
  xssFilter: true,
  noSniff: true,
  hidePoweredBy: true
}));

// 2. Rate Limiting
const limiter = rateLimit({
  windowMs: 60 * 1000, // 1 minute
  max: 60, // 60 requests per minute
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later in 1 minute.' }
});
app.use(limiter);

// 3. Input Validation Utilities
const validators = {
  email: (str) => validator.isEmail(str),
  username: (str) => validator.escape(str).length >= 3 && validator.escape(str).length <= 20,
  text: (str) => validator.isAlphanumeric(str.replace(/[\\s.,!?]/g, '')) && str.trim().length > 0,
  integer: (num) => Number.isInteger(parseInt(num))
};

function validateNestedPath(str) {
  const parts = str.split('/');
  return parts.every(part => validator.escape(part) === part);
}

function validateRequestBody(req, schema) {
  for (const [field, rule] of Object.entries(schema)) {
    if (req.body[field] === undefined) {
      return { valid: false, field, message: `${field} is required` };
    }
    if (rule.type === 'email' && !validators.email(req.body[field])) {
      return { valid: false, field, message: 'Invalid email format' };
    }
    if (rule.type === 'username' && !validators.username(req.body[field])) {
      return { valid: false, field, message: 'Username must be 3-20 alphanumeric characters' };
    }
    if (rule.regex && !rule.regex.test(req.body[field])) {
      return { valid: false, field, message: rule.message || `${field} is invalid` };
    }
  }
  return { valid: true };
}

// 4. Authentication Middleware
const config = {
  jwtSecret: secrets.jwtSecret,
  port: secrets.port,
  nodeEnv: secrets.nodeEnv
};

function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader?.startsWith('Bearer ') ? authHeader.split(' ')[1] : null;

  if (!token) {
    return res.status(401).json({ error: 'Access denied. No token provided.' });
  }

  jwt.verify(token, config.jwtSecret, (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid or expired token.' });
    }
    req.user = user;
    next();
  });
}

// 5. Error Handling middleware
app.use((err, req, res, next) => {
  console.error('Error:', err);
  res.status(err.status || 500).json({
    error: err.message || 'Internal server error',
    stack: config.nodeEnv === 'development' ? err.stack : undefined
  });
});

// Secure Health Endpoint (Fedora: Timestamp - kept as timestamp for debugging)
app.get('/health', (req, res) => {
  res.status(200).json({
    status: 'ok',
    timestamp: new Date().toISOString()
  });
});

// Protected User Endpoint
app.get('/users', authenticateToken, (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' }
  ]);
});

// Start server on secured port
app.listen(config.port, () => {
  console.log(`Server running on port ${config.port}`);
  console.log(`Environment: ${config.nodeEnv}`);
});

module.exports = app;

