### Option 2: Enterprise Approach (Recommended)

**For production applications:**

```javascript
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');
const { VaultClient } = require('node-vault');
const logger = require('./logger');

class SecretManager {
  constructor() {
    this.secrets = {};
  }

  async initialize() {
    logger.info('Initializing Secret Manager');

    // If AWS and KMS key is configured, try AWS Secrets Manager
    if (process.env.ENABLE_AWS_SECRET_MANAGER === 'true') {
      await this.loadAWSSecrets();
    }
    // Otherwise, fallback to environment variables
    else {
      await this.loadEnvSecrets();
    }

    this.validateSecrets();
  }

  async loadAWSSecrets() {
    const client = new SecretsManagerClient({
      region: process.env.AWS_REGION || 'us-east-1'
    });

    const secretIds = [
      'prod/database-credentials',
      'prod/api-keys',
      'prod/config'
    ];

    for (const secretId of secretIds) {
      try {
        const command = new GetSecretValueCommand({ SecretId: secretId });
        const response = await client.send(command);
        this.secrets = { ...this.secrets, ...JSON.parse(response.SecretString) };
        logger.info(`Loaded secret: ${secretId}`);
      } catch (error) {
        logger.warn(`Failed to load secret ${secretId}:`, error.message);
      }
    }
  }

  async loadEnvSecrets() {
    const requiredSecrets = ['DATABASE_URL', 'JWT_SECRET', 'JWT_EXPIRES_IN'];
    for (const secret of requiredSecrets) {
      if (!process.env[secret]) {
        throw new Error(`Missing required secret: ${secret}`);
      }
      this.secrets[secret] = process.env[secret];
    }

    // Warn about potential .env exposure
    if (process.env.NODE_ENV !== 'production') {
      logger.warn('⚠️ Running with .env secrets instead of secret manager');
    }
  }

  validateSecrets() {
    // Database URL validation
    if (!this.secrets.DATABASE_URL?.startsWith('postgres://') &&
        !this.secrets.DATABASE_URL?.startsWith('mongodb://')) {
      throw new Error('Invalid DATABASE_URL format');
    }

    // JWT Secret strength check
    if (this.secrets.JWT_SECRET?.length < 32) {
      throw new Error('JWT_SECRET must be at least 32 characters');
    }

    logger.info('All secrets validated successfully');
  }

  get(key) {
    return this.secrets[key];
  }
}

const secretManager = new SecretManager();

module.exports = { secretManager };
```

**Usage in app.js:**

