```javascript
function validateSecret(
  name,
  value,
  options = {
    minLength: 0,
    allowedValues: null,
    pattern: null
  }
) {
  if (!value) {
    throw new Error(`Secret "${name}" is missing`);
  }

  if (options.minLength && value.length < options.minLength) {
    throw new Error(`Secret "${name}" is too short (minimum ${options.minLength} chars)`);
  }

  if (options.allowedValues && !options.allowedValues.includes(value)) {
    throw new Error(`Invalid value for secret "${name}"`);
  }

  if (options.pattern && !options.pattern.test(value)) {
    throw new Error(`Secret "${name}" doesn't match required pattern`);
  }
}
```

### 4. Mask Secrets in Logs

```javascript
const winston = require('winston');

const secretMask = (string) => {
  if (!string) return string;
  return string.replace(/(password|token|secret|key|credential)[^=]*=[^ ]*/,
    '$1=***REDACTED***');
};

const logger = winston.createLogger({
