        message: secretMask(info.message),
        data: info.data ? JSON.parse(JSON.stringify(info.data, replacer)) : undefined
      };
    }
  })
});

const replacer = (key, value) => {
  if (typeof value === 'string' && /secret|password|token|key|credential/i.test(key)) {
    return '***REDACTED***';
  }
  return value;
};
