const fs = require('fs');
const path = require('path');

class SecretManager {
  constructor() {
    this.secrets = null;
  }

  load() {
    const envPath = path.join(process.cwd(), process.env.NODE_ENV === 'production' 
      ? '.env.production' 
      : '.env.local');

    if (!fs.existsSync(envPath)) {
      throw new Error(`Environment file not found: ${envPath}`);
    }

    const envContent = fs.readFileSync(envPath, 'utf8');
    const lines = envContent.split('\n');

    this.secrets = {};

    for (const line of lines) {
      if (line.startsWith('#') || !line.trim()) continue;

      const match = line.match(/^([^=]+)=(.*)$/);
      if (match) {
        const key = match[1].trim();
        const value = match[2].trim();

        // Validate required secrets exist
        if (this.isRequiredSecret(key)) {
          if (!value) {
            throw new Error(`Required secret not configured: ${key}`);
          }
        }

        this.secrets[key] = value;
      }
    }

    return this.secrets;
  }

  get(key) {
    if (!this.secrets) {
      this.secrets = this.load();
    }

    // Process secret (only in development)
    if (process.env.NODE_ENV !== 'production' && this.secrets[key]) {
      return this.maskSensitiveValue(this.secrets[key], key);
    }

    return this.secrets[key];
  }

  isRequiredSecret(key) {
    return [
      'DATABASE_URL',
      'AWS_ACCESS_KEY_ID',
      'AWS_SECRET_ACCESS_KEY',
      'ANTHROPIC_API_KEY',
      'STRIPE_SECRET_KEY',
      'JWT_SECRET'
    ].includes(key);
  }

  maskSensitiveValue(value, key) {
    if (value.length > 8) {
      return value.substring(0, 4) + '***' + value.substring(value.length - 4);
    }
    return '***HIDDEN***';
  }
}

module.exports = new SecretManager();
```

