# Security Review of app.js

## Executive Summary
**Overall Risk Level: HIGH** - This application contains multiple critical security vulnerabilities that would allow exploitation. The application lacks proper authentication, input validation, authorization, and security best practices.

---

## Critical Vulnerabilities

### 1. **Broken Access Control (OWASP A01:2021)**
**Severity: HIGH**

**Issue:** The `/users` endpoint provides unauthenticated access to potentially sensitive user data. Anyone can access a list of users without any authentication requirements.

**Current Code:**
```javascript
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

**Recommended Fix - Add Authentication:**
```javascript
const jwt = require('jsonwebtoken');

// Middleware to verify JWT token
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
}

// Apply authentication middleware
app.get('/users', authenticateToken, (req, res) => {
  res.json(getUsers(req.user.role)); // Role-based access
});
```

**Alternative - Use Session-Based Auth:**
```javascript
const session = require('express-session');
const bcrypt = require('bcrypt');

app.use(session({
  secret: process.env.SESSION_SECRET,
  resave: false,
  saveUninitialized: false,
  cookie: { secure: process.env.NODE_ENV === 'production' }
}));

app.post('/login', async (req, res) => {
  const { email, password } = req.body;

  // Validate input (see input validation below)
  if (!email || !password) {
    return res.status(400).json({ error: 'Email and password required' });
  }

  // Check if user exists (properly implemented in real app)
  const user = await getUserByEmail(email);

  if (!user || !(await bcrypt.compare(password, user.passwordHash))) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  req.session.userId = user.id;
  req.session.role = user.role;
  res.json({ message: 'Login successful' });
});
```

---

### 2. **Missing Input Validation (OWASP A08:2021)**
**Severity: MEDIUM-HIGH**

**Issue:** No validation on request parameters or body data. This makes the application vulnerable to:
- Malformed data causing server crashes
- Injection attacks
- Broken data handling

**Current Code:**
```javascript
app.get('/users', (req, res) => {
  // No validation of request parameters
});
```

**Recommended Fix - Request Validation:**
```javascript
const Joi = require('joi');

// Schema validation
const userSchema = Joi.object({
  name: Joi.string().min(2).max(100).pattern(/^[a-zA-Z\s]+$/).required(),
  email: Joi.string().email({ minDomainSegments: 2, tlds: { allow: ['com', 'org'] } }).required(),
});

const loginSchema = Joi.object({
  email: Joi.string().email().required(),
  password: Joi.string().min(8).pattern(/(?=.*\d)(?=.*[a-z])(?=.*[A-Z])/).required()
});

// Validate login endpoint
app.post('/login', async (req, res) => {
  const { error } = loginSchema.validate(req.body);
  if (error) {
    return res.status(400).json({
      error: 'Validation failed',
      details: error.details.map(d => ({ field: d.path.join('.'), message: d.message }))
    });
  }

  // Process login...
});

// Validate user creation endpoint
app.post('/users', async (req, res) => {
  const { error } = userSchema.validate(req.body);
  if (error) {
    return res.status(400).json({
      error: 'Invalid input data',
      details: error.details
    });
  }

  // Process user creation...
});
```

---

### 3. **Information Disclosure (OWASP A05:2021 - Security Misconfiguration)**
**Severity: MEDIUM**

**Issue:** No CORS headers configured, allowing any origin to make requests. Exposes important headers that aid in debugging and reconnaissance.

**Recommended Fix - Configure CORS:**
```javascript
const cors = require('cors');

const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 86400 // 24 hours
};

app.use(cors(corsOptions));
app.use(cors()); // Fallback

// Set security headers
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
  res.setHeader('Permissions-Policy', 'geolocation=(), microphone=(), camera=()');
  next();
});
```

---

### 4. **No Rate Limiting**
**Severity: MEDIUM-HIGH**

**Issue:** No rate limiting makes the application vulnerable to:
- Denial of Service attacks
- Brute force attacks
- Abuse of endpoints

**Recommended Fix - Add Rate Limiting:**
```javascript
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');

// Apply helmet for security headers
app.use(helmet());

// Basic rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later'
  },
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(limiter);

// Apply stricter limit to auth endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // Only 5 attempts per 15 minutes
