**Problem:** All users see all users regardless of their role.

**Recommended Fix - Role-Based Access Control:**
```javascript
function authorize(roles = []) {
  return (req, res, next) => {
    if (roles.length && !roles.includes(req.user.role)) {
      return res.status(403).json({ error: 'Insufficient permissions' });
    }
    next();
  };
}

// Middleware to ensure user is authenticated and has role
function requireAuth(req, res, next) {
  if (!req.user) {
    return res.status(401).json({ error: 'Authentication required' });
  }
  next();
}

// Admin only routes
