### 9. **No Request Logging with Sensitive Data Masking**
**Severity: LOW-MEDIUM**

**Recommended Fix - Security-Aware Logging:**
```javascript
const morgan = require('morgan');
const winston = require('winston');

// Log format that masks sensitive data
const logFormat = winston.format.printf(({ level, message, timestamp, req, res }) => {
  const sanitizedRequest = {
    method: req.method,
    url: req.url,
    ip: req.ip,
    query: req.query,
    body: maskSensitiveData(req.body),
    // Don't log headers in production
  };

  return `${timestamp} [${level}]: ${message} - ${JSON.stringify(sanitizedRequest)}`;
});

const logger = winston.createLogger({
  level: 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    logFormat
  ),
  transports: [
    new winston.transports.Console(),
    new winston.transports.File({ filename: 'error.log', level: 'error' })
  ]
});

function maskSensitiveData(data) {
  if (!data) return undefined;
  if (Array.isArray(data)) {
    return data.map(maskSensitiveData);
  }
  if (typeof data === 'object') {
    const masked = { ...data };
    if (masked.password) masked.password = '***REDACTED***';
    if (masked.email) masked.email = masked.email.replace(/(.{2})(.*)(@.*)/, '$1***$3');
    if (masked.token) masked.token = masked.token.substring(0, 10) + '...';
    return masked;
  }
  return data;
}

app.use(morgan('combined', { stream: logger.stream }));
```

