## Complete Secure Example

```javascript
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const validator = require('express-validator');
const { body, param } = validator;
const jwt = require('jsonwebtoken');
const bcrypt = require('bcrypt');
const dotenv = require('dotenv');
const winston = require('winston');
const knex = require('knex');

// Configuration
dotenv.config();

const app = express();
const PORT = process.env.PORT || 3000;

// Security middleware
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'"],
      imgSrc: ["'self'", "data:"],
    },
  },
  hsts: { maxAge: 31536000, includeSubDomains: true }
}));

app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true
}));

app.use(express.json({ limit: '1mb' }));
app.use(express.urlencoded({ extended: true, limit: '1mb' }));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  message: 'Too many requests. Please try again later'
});

const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  message: 'Too many login attempts'
});

app.use(limiter);

// Error logging with sensitive data masking
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.json()
  ),
  transports: [
    new winston.transports.Console(),
    new winston.transports.File({ filename: 'combined.log' })
  ]
});

// Authentication middleware
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
}

// Resource access control middleware
function authorize(roles) {
  return (req, res, next) => {
    if (roles.length && !roles.includes(req.user.role)) {
      return res.status(403).json({ error: 'Insufficient permissions' });
    }
    next();
  };
}

// Routes
app.get('/health', authenticateToken, (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    user: req.user.id
  });
});

app.get('/users',
  authenticateToken,
  authorize(['user', 'admin']),
  validator.query('page').optional().isInt({ min: 1 }),
  validator.query('limit').optional().isInt({ min: 1, max: 100 }),
  (req, res) => {
    const { page = 1, limit = 10 } = req.query;

    getUserList(req.user.id, page, limit)
      .then(users => res.json(users))
      .catch(err => next(err));
  }
);

app.get('/users/:id',
  authenticateToken,
  authorize(['user', 'admin']),
  param('id').isInt().withMessage('User ID must be an integer'),
  (req, res, next) => {
    const errors = validator.validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    getUserById(req.params.id, req.user.id, req.user.role)
      .then(user => {
        if (!user) return res.status(404).json({ error: 'User not found' });
        res.json(user);
      })
      .catch(err => next(err));
  }
);

app.post('/login',
  authLimiter,
  validator.body('email').isEmail(),
  validator.body('password').isLength({ min: 8 }),
  async (req, res) => {
    const errors = validator.validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const { email, password } = req.body;

    try {
      const user = await authUser(email, password);
      if (!user) {
        return res.status(401).json({ error: 'Invalid credentials' });
      }

      const token = jwt.sign(
        { id: user.id, email: user.email, role: user.role },
        process.env.JWT_SECRET,
        { expiresIn: '24h' }
      );

      const refreshToken = jwt.sign(
        { id: user.id },
        process.env.JWT_REFRESH_SECRET,
        { expiresIn: '7d' }
      );

      res.json({
        message: 'Login successful',
        user: { id: user.id, name: user.name, email: user.email },
        accessToken: token,
        refreshToken
      });
    } catch (error) {
      next(error);
    }
  }
);

// Database function examples
async function getUserList(userId, page, limit) {
  const query = db('users')
    .select('id', 'name', 'email')
    .where('id', '<>', userId); // Don't show self to non-admin

  const [countResult] = await query.clone().count();
  const total = Number(countResult.count);

  return {
    data: await query.offset((page - 1) * limit).limit(limit),
    pagination: {
      page: Number(page),
      limit: Number(limit),
      total
    }
  };
}

async function getUserById(id, userId, role) {
  if (role === 'admin') {
    return await db('users').where('id', id).first();
  }
  return await db('users').where({
    id,
    user_id: userId // Security: user can only view their own data
  }).first();
}

async function authUser(email, password) {
  const user = await db('users').where('email', email).first();

  if (!user) {
    return null;
  }

  return await bcrypt.compare(password, user.password_hash) ? user : null;
}

// Error handling
app.use((err, req, res, next) => {
  logger.error('Error:', {
    message: err.message,
    stack: err.stack,
    url: req.url,
    method: req.method,
    ip: req.ip
  });

  res.status(err.status || 500).json({
    error: process.env.NODE_ENV === 'development' ? err.message : 'Internal server error'
  });
});

app.listen(PORT, () => {
  logger.info(`Secure server running on port ${PORT}`);
});
```

