### 7. **No Encryption at Rest**
**Severity**: LOW to MEDIUM
**Location**: Future data storage

**Problem**: If database connection strings or data aren't encrypted in transit and at rest.

**Recommendation**:
- Use TLS for all database connections
- Encrypt sensitive data before storing
- Use encryption libraries like `crypto`

```javascript
const crypto = require('crypto');

// Encrypt data before storing
function encrypt(data, key) {
    const iv = crypto.randomBytes(16);
    const cipher = crypto.createCipheriv('aes-256-cbc', Buffer.from(key), iv);
    let encrypted = cipher.update(data);
    encrypted = Buffer.concat([encrypted, cipher.final()]);
    return {
        iv: iv.toString('hex'),
        content: encrypted.toString('hex')
    };
}

// Decrypt data when reading
function decrypt(encryptedData, key) {
    const decipher = crypto.createDecipheriv(
        'aes-256-cbc',
        Buffer.from(key),
        Buffer.from(encryptedData.iv, 'hex')
    );
    let decrypted = decipher.update(Buffer.from(encryptedData.content, 'hex'));
    decrypted = Buffer.concat([decrypted, decipher.final()]);
    return decrypted.toString();
}

// Encrypt sensitive user data
const encryptedEmail = encrypt('alice@example.com', process.env.ENCRYPTION_KEY);
```

