### 9. **Secure Cookie Configuration (for future use)**
**Severity**: LOW
**Location**: Future authentication

**Recommendation**:
- Use HTTPS for all sessions
- Set `httpOnly` flag for cookies
- Set `secure` flag for production
- Use short expiration times
- Use `SameSite` attribute

```javascript
const cookieParser = require('cookie-parser');

app.use(cookieParser());

// Example secure cookie for JWT
app.post('/login', authenticateUser, (req, res) => {
    const token = jwt.sign(
        { userId: req.user.id },
        process.env.JWT_SECRET,
        { expiresIn: '15m' }
    );

    res.cookie('token', token, {
        httpOnly: true,
        secure: process.env.NODE_ENV === 'production',
        sameSite: 'strict',
        maxAge: 15 * 60 * 1000, // 15 minutes
        domain: process.env.COOKIE_DOMAIN
    });

    res.redirect('/dashboard');
});

// Secure logout
app.post('/logout', (req, res) => {
    res.clearCookie('token', {
        httpOnly: true,
        secure: process.env.NODE_ENV === 'production',
        sameSite: 'strict'
    });
    res.json({ message: 'Logged out successfully' });
});
```

---

### 10. **HTTPS & SSL/TLS**
**Severity**: HIGH (if serving to public)
**Location**: Server configuration

**Recommendation**:
- Use `express-httpsify` or configure Node.js to use HTTPS
- Use a certificate from Let's Encrypt or commercial CA
- Use HSTS (HTTP Strict Transport Security)

```javascript
const https = require('https');
const fs = require('fs');
const path = require('path');

// ℹ️ For development, you can use self-signed certificates
const sslOptions = {
    key: fs.readFileSync(path.join(__dirname, 'certs', 'key.pem')),
    cert: fs.readFileSync(path.join(__dirname, 'certs', 'cert.pem')),
    ca: fs.readFileSync(path.join(__dirname, 'certs', 'ca.pem')),
};

app.enable('trust proxy'); // Trust reverse proxies

// HSTS middleware
const helmet = require('helmet');
const hsts = helmet.hsts();

if (process.env.NODE_ENV === 'production') {
    app.use(helmet({
        hsts: {
            maxAge: 31536000, // 1 year in seconds
            includeSubDomains: true,
            preload: true
        }
    }));
}

// Start HTTPS server
const PORT = process.env.PORT || 443;
https.createServer(sslOptions, app).listen(PORT, () => {
    console.log(`🔐 HTTPS server running on port ${PORT}`);
});
```

