/**
 * Secure version of the application
 * This demonstrates recommended security practices for an Express.js application
 */

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');
const path = require('path');
const https = require('https');
const fs = require('fs');

// Initialize Express app
const app = express();

// Security headers middleware
app.use(helmet({
    contentSecurityPolicy: {
        directives: {
            defaultSrc: ["'self'"],
            styleSrc: ["'self'", 'https://fonts.googleapis.com'],
            scriptSrc: ["'self'"],
            imgSrc: ["'self'", 'data:', 'https:'],
        }
    },
    hsts: {
        maxAge: 31536000,
        includeSubDomains: true,
        preload: true
    },
    noSniff: true,
    xssFilter: true,
    frameguard: { action: 'deny' },
    noCache: true,
    referrerPolicy: { policy: 'strict-origin-when-cross-origin' }
}));

// CORS configuration
const allowedOrigins = process.env.ALLOWED_ORIGINS
    ? process.env.ALLOWED_ORIGINS.split(',')
    : ['http://localhost:3000'];

app.use(cors({
    origin: function(origin, callback) {
        if (!origin) return callback(null, true);
        if (allowedOrigins.indexOf(origin) === -1) {
            const msg = 'The CORS policy for this site does not ' +
                'allow access from the specified Origin';
            return callback(new Error(msg), false);
        }
        return callback(null, true);
    },
    credentials: true,
    methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
    allowedHeaders: ['Content-Type', 'Authorization']
}));

// Parse JSON bodies
app.use(express.json({ limit: '10kb' }));

// Parse URL-encoded bodies
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Rate limiting
const limiter = rateLimit({
    windowMs: 15 * 60 * 1000, // 15 minutes
    max: 100, // limit each IP to 100 requests per windowMs
    message: {
        error: 'Too many requests from this IP, please try again later'
    },
    standardHeaders: true,
    legacyHeaders: false,
    validate: {
        trustProxy: true
    }
});

// Apply rate limiting to all routes except health check
app.use(limiter);

// Health check endpoint - limited to prevent DoS
app.get('/health', limiter, (req, res) => {
    const healthData = {
        status: 'ok',
        timestamp: new Date().toISOString(),
        uptime: process.uptime(),
        memoryUsage: process.memoryUsage()
    };

    // Only include sensitive info in development
    if (process.env.NODE_ENV === 'development') {
        healthData.app = {
            port: process.env.PORT || 3000,
            nodeVersion: process.version,
            platform: process.platform
        };
    }

    res.json(healthData);
});

// Example validated route
app.get('/users/:id', [
    param('id').isInt({ min: 1 }).withMessage('ID must be a positive integer')
], validateRequest, (req, res) => {
    const userId = parseInt(req.params.id);

    // Simulated user data (in production, this would come from a database)
    const user = {
        id: userId,
        name: 'Alice',
        email: 'alice@example.com'
    };

    res.json({
        success: true,
        data: user
    });
});

// Request validation middleware
function validateRequest(req, res, next) {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
        return res.status(400).json({
            success: false,
            errors: errors.array({ type: 'field' })
        });
    }
    next();
}

// Error handling middleware
app.use((err, req, res, next) => {
    // Log error in production
    if (process.env.NODE_ENV === 'production') {
        console.error('Error:', err);
        // In production, send generic error message
        return res.status(err.status || 500).json({
            success: false,
            error: 'Internal Server Error'
        });
    }

    // Detailed error in development
    console.error('Error:', err.stack);
    res.status(err.status || 500).json({
        success: false,
        error: err.message,
        stack: err.stack
    });
});

// 404 Handler
app.use((req, res) => {
    res.status(404).json({
        success: false,
        error: 'Endpoint not found',
        path: req.path
    });
});

// Log listening
const port = process.env.PORT || 3000;
app.listen(port, () => {
    console.log(`✅ Server running on port ${port}`);
    console.log(`🌍 Environment: ${process.env.NODE_ENV || 'development'}`);
    console.log(`🛡️  Security headers: Configured`);
    console.log(`🔒 CORS: ${allowedOrigins.join(', ')}`);
});

module.exports = app;

// Export for testing
if (require.main === module) {
    // Only start HTTPS server if running directly and certificates exist
    if (process.env.NODE_ENV === 'production') {
        const sslOptions = {
            key: fs.readFileSync(path.join(__dirname, 'ssl', 'localhost-key.pem')),
            cert: fs.readFileSync(path.join(__dirname, 'ssl', 'localhost-cert.pem')),
        };

        const sslPort = 443;
        https.createServer(sslOptions, app).listen(sslPort, () => {
            console.log(`🔐 HTTPS server running on port ${sslPort}`);
        });
    }
}

