/**
 * Environment Variables Loader with Security Validation
 * Loads and validates secrets at startup to prevent runtime errors
 */

const path = require('path');
const fs = require('fs');
const crypto = require('crypto');

// Check if .env file exists
function envFileExists() {
    try {
        return fs.existsSync('.env');
    } catch (error) {
        console.error('Error checking .env file:', error);
        return false;
    }
}

// Read .env file
function loadEnvFile(envPath = '.env') {
    if (!fs.existsSync(envPath)) {
        console.warn(`⚠️  Warning: ${envPath} not found. Using default values.`);
        return {};
    }

    try {
        const envPathResolved = path.resolve(process.cwd(), envPath);
        const envContent = fs.readFileSync(envPathResolved, 'utf-8');
        const envConfig = {};

        envContent.split('\n').forEach(line => {
            // Skip empty lines, comments, and 'if' statements
            if (!line || line.startsWith('#') || line.startsWith('if ')) {
                return;
            }

            // Handle export statements
            const splitLine = line.trim().replace(/^export\s+/, '').split('=');
            if (splitLine.length >= 2) {
                const key = splitLine[0].trim();
                let value = splitLine.slice(1).join('=').trim();

                // Remove quotes if present
                if ((value.startsWith('"') && value.endsWith('"')) ||
                    (value.startsWith("'") && value.endsWith("'"))) {
                    value = value.slice(1, -1);
                }

                envConfig[key] = value;
            }
        });

        return envConfig;
    } catch (error) {
        console.error('Error reading .env file:', error);
        process.exit(1);
    }
}

// Validate that required environment variables are set
function validateRequiredEnvVars(requiredVars, customMessage = 'Required environment variable') {
    const missingVars = [];

    requiredVars.forEach(varName => {
        if (!process.env[varName]) {
            missingVars.push(varName);
        }
    });

    if (missingVars.length > 0) {
        const message = `${customMessage}: ${missingVars.join(', ')}`;
        console.error(`❌ CRITICAL ERROR: ${message}`);
        console.log('\n💡 To fix this, create a .env file with the following variable(s):');
        missingVars.forEach(varName => {
            console.log(`   ${varName}=<value>`);
        });
        console.log('\n📝 You can use: openssl rand -base64 32');
        process.exit(1);
    }
}

// Validate that environment variable has valid format
function validateEnvVarFormat(varName, validator) {
    const value = process.env[varName];
    if (!value) {
        console.error(`❌ CRITICAL ERROR: Required environment variable "${varName}" is missing`);
        process.exit(1);
    }

    const validation = validator(value);
    if (!validation.isValid) {
        console.error(`❌ CRITICAL ERROR: Environment variable "${varName}" has invalid format: "${value}"`);
        console.error(`   Error: ${validation.error}`);
        if (validation.example) {
            console.error(`   Example: ${validation.example}`);
        }
        process.exit(1);
    }

    return value;
}

// Generate a secure random secret for a .env file
function generateSecureSecret(baseName = 'SECRET') {
    const secret = crypto.randomBytes(32).toString('base64');
    return `${baseName}_${Date.now()}_${secret}`;
}

// Generate multiple secrets
function generateSecrets(count = 3) {
    const secrets = {};

    for (let i = 0; i < count; i++) {
        secrets[`SECRET_${i + 1}`] = generateSecureSecret(`SECRET_${i + 1}`);
    }

    return secrets;
}

module.exports = {
    envFileExists,
    loadEnvFile,
    validateRequiredEnvVars,
    validateEnvVarFormat,
    generateSecureSecret,
    generateSecrets
};

