    windowMs: windowSize,
    max: maxRequests,
    message: { error: 'Rate limit exceeded' },
    skipSuccessfulRequests: false,
    // Use memory store by default (not for production without scaling)
    store: new rateLimit.MemoryStore()
  });
};

// Very strict for sensitive operations
