  // Data export logic
});

// IP-based rate limiting (for multi-port environments)
const ipLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 1000, // More lenient for total traffic but IP-based
  keyGenerator: (req) => req.ip,
  standardHeaders: true,
  legacyHeaders: false,
});

app.use('/api', ipLimiter);

// Redis-backed rate limiting for production
const { RateLimiterMemory } = require('rate-limiter-flexible');
const Redis = require('ioredis');
const redis = new Redis(process.env.REDIS_URL);

const rateLimiterRedis = new RateLimiterMemory({
  keyPrefix: 'api',
  points: 100,
  duration: 15 * 60, // 15 minutes
  storageClient: new Redis({ ... }),
});

app.use(async (req, res, next) => {
  // Get rate limit info from Redis
  const { totalHits, remainingPoints, msBeforeNext } = await rateLimiterRedis.get(req.ip);

  res.set('X-RateLimit-Limit', totalHits);
  res.set('X-RateLimit-Remaining', remainingPoints);
  res.set('X-RateLimit-Reset', msBeforeNext);
  res.set('Retry-After', msBeforeNext / 1000);

  // If we have consumed all points, response with 429 status
  if (remainingPoints <= 0) {
    return res.status(429).json({ error: 'Rate limit exceeded' });
  }

  next();
});
