```javascript
// Centralized error handling
const errorHandler = (err, req, res, next) => {
  // Log detailed error info
  console.error('[Error]', {
    timestamp: new Date().toISOString(),
    requestId: req.id,
    ip: req.ip,
    url: req.originalUrl,
    method: req.method,
    error: {
      name: err.name,
      message: err.message,
      stack: err.stack
    }
  });

  // Don't expose sensitive details in production
  const isProduction = process.env.NODE_ENV === 'production';

  if (err.statusCode && err.statusCode >= 400 && err.statusCode < 500) {
    // Client errors - show status and custom message
    res.status(err.statusCode).json({
      error: err.message || 'Bad Request',
      requestId: req.id
    });
  } else if (isProduction) {
    // Server errors - generic message only
    res.status(500).json({
      error: 'An unexpected error occurred. Our team has been notified.',
      requestId: req.id
    });
  } else {
    // Development - detailed error info
    res.status(500).json({
      message: err.message,
      stack: err.stack,
      requestId: req.id
    });
  }
};

// Mount error handler
app.use(errorHandler);

// Add custom error classes
class UnauthorizedError extends Error {
  constructor(message = 'Unauthorized') {
    super(message);
    this.statusCode = 401;
  }
}

class ForbiddenError extends Error {
  constructor(message = 'Forbidden') {
    super(message);
    this.statusCode = 403;
  }
}

class NotFoundError extends Error {
  constructor(message = 'Resource not found') {
    super(message);
    this.statusCode = 404;
  }
}

class ValidationError extends Error {
  constructor(message) {
    super(message);
    this.statusCode = 400;
  }
}

class ConflictError extends Error {
  constructor(message = 'Resource already exists') {
    super(message);
    this.statusCode = 409;
  }
}

app.use((err, req, res, next) => {
  // For custom errors, use them directly
  if (err instanceof UnauthorizedError) {
    return res.status(err.statusCode).json({ error: err.message });
  }

  if (err instanceof ForbiddenError) {
    return res.status(err.statusCode).json({ error: err.message });
  }

  if (err instanceof NotFoundError) {
    return res.status(err.statusCode).json({ error: err.message });
  }

  if (err instanceof ConflictError) {
    return res.status(err.statusCode).json({ error: err.message });
  }

  // Handle validation errors
  if (err.errors && Array.isArray(err.errors) && err.errors[0].constraint) {
    return res.status(400).json({
      error: 'Validation failed',
      details: err.errors
    });
  }

  // Default to 500 for unexpected errors
  next(err);
});

// Validation error handling (for express-validator)
const validate = (validations) => {
  return async (req, res, next) => {
    await Promise.all(validations.map(validation => validation.run(req)));
    const errors = validationResult(req);

    if (!errors.isEmpty()) {
      return res.status(422).json({
        error: 'Validation failed',
        details: errors.array()
      });
    }

    next();
  };
};
