// Install: npm install @aws-sdk/secrets-manager @azure/keyvault-secrets @google-cloud/secret-manager

class SecretsManager {
  constructor() {
    this.secrets = {};
  }

  async load(secretName, providerType) {
    if (this.secrets[secretName]) {
      return this.secrets[secretName];
    }

    if (providerType === 'aws') {
      const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/secrets-manager');
      const client = new SecretsManagerClient({ region: process.env.AWS_REGION });
      const response = await client.send(new GetSecretValueCommand({ SecretId: secretName }));
      this.secrets[secretName] = JSON.parse(response.SecretString);
    } 
    else if (providerType === 'azure') {
      const { SecretClient } = require('@azure/keyvault-secrets');
      const client = new SecretClient(process.env.AZURE_VAULT_URL);
      const secret = await client.getSecret(secretName);
      this.secrets[secretName] = secret.value;
    }
    else if (providerType === 'gcp') {
      const { SecretManagerServiceClient } = require('@google-cloud/secret-manager');
      const client = new SecretManagerServiceClient();
      const [version] = await client.accessSecretVersion({ name: secretName });
      this.secrets[secretName] = version.payload.data.toString('base64');
    }

    return this.secrets[secretName];
  }
}

module.exports = new SecretsManager();
