        // Payment (production only)
        STRIPE_SECRET_KEY: Joi.string().when('NODE_ENV', {
            is: 'production',
            then: Joi.string().pattern(/^sk_live_|^sk_test_/).required(),
            otherwise: Joi.string().pattern(/^sk_test_/).optional()
        }),

        // Tokens
        LOGFIRE_TOKEN: Joi.string().optional(),

        // JWT
        JWT_SECRET: Joi.string().min(32).required(),
        JWT_EXPIRES_IN: Joi.string().default('1h'),

        // Server
        PORT: Joi.string().default('3000'),
        CORS_ORIGIN: Joi.string().uri().default('http://localhost:3000')
    });

    const { error, value } = schema.validate(process.env, {
        allowUnknown: true,
        abortEarly: false
    });

    if (error) {
        console.error('❌ Environment validation failed:');
        error.details.forEach(detail => {
            console.error(`  - ${detail.path.join('.')}: ${detail.message}`);
        });
        process.exit(1);
    }

    console.log('✅ Environment configuration validated successfully');
}

module.exports = { validateEnvironment };
```

**5. Update `app.js` to use the secrets properly:**
```javascript
